from openpyxl import load_workbook
from datetime import time

path = '/workspace/task/output.xlsx'
wb = load_workbook(path)
ws = wb['Edit']

hdr = {}
for c in range(6, 47):
    hdr[c] = ws.cell(row=1, column=c).value

def parse(s):
    h, m = map(int, s.split(':'))
    return time(h, m)

def find_blocks(row):
    mcols = [c for c in range(6, 47) if ws.cell(row=row, column=c).value == 'm']
    blocks = []
    for c in mcols:
        if blocks and c == blocks[-1][-1] + 1:
            blocks[-1].append(c)
        else:
            blocks.append([c])
    return blocks

for r in range(2, 17):
    blocks = find_blocks(r)
    vals = []
    for blk in blocks[:2]:
        vals.append(parse(hdr[blk[0]]))   # start
        vals.append(parse(hdr[blk[-1]]))  # finish
    # write into B,C,D,E
    for i, col in enumerate(range(2, 6)):
        ws.cell(row=r, column=col).value = vals[i] if i < len(vals) else None

wb.save(path)
print("done")
EOF
